SELECT DATE_TRUNC('QUARTER', start_date) AS quarter_start, CASE WHEN monthly_fee >= 186 THEN 'LARGE' ELSE 'SMALL' END AS monthly_fee_tier, ROUND(SUM(monthly_fee) / NULLIF(COUNT(CASE WHEN plan = 'standard' THEN 1 END), 0), 2) AS monthly_fee_per_standard, COUNT(*) AS num_rows, COUNT_IF(status = 'CANCELLED') AS cancelled_events, SORT_ARRAY(COLLECT_SET(status)) AS status_list, COUNT(*) FILTER (WHERE status = 'EXPIRED') AS expired_rows FROM subscriptions GROUP BY 1, 2
